'use strict';
// Time-lapse of distinct SSEC observations. No image is translated or rotated to fake wind.
(function(root){
function bundledSequence(){try{return root.GeoData?root.GeoData.sequence():Promise.resolve(root.GEO_WEATHER_SEQUENCE||null);}catch(error){return Promise.resolve(null);}}
function parseStamp(value){const m=/^(\d{4})(\d{2})(\d{2})[._](\d{2})(\d{2})(\d{2})$/.exec(value||'');return m?Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+m[6]):null;}
class WeatherPlayback{
 constructor(controller){this.controller=controller;this.playing=false;this.loading=false;this.timer=null;this.abort=null;this.hoursPerSecond=4.5;this.frames=[];this.index=0;this.generation=0;this.button=document.getElementById('weatherPlay');this.label=document.getElementById('weatherPlaybackStatus');this.button.onclick=()=>this.playing||this.loading?this.stop():this.prepare();document.getElementById('weatherPlaybackSpeed').onchange=e=>{this.hoursPerSecond=Number(e.target.value)||4.5;};this.frameCount=24;const frames=document.getElementById('weatherFrames');if(frames){this.frameCount=Number(frames.value)||24;frames.addEventListener('change',e=>{this.frameCount=Number(e.target.value)||24;this.stop();});}for(const id of ['weatherProduct','weatherTime'])document.getElementById(id).addEventListener('change',()=>this.stop());const refresh=controller.refresh.bind(controller);controller.refresh=async()=>{const wasPlaying=this.playing;this.stop();await refresh();if(wasPlaying&&!root.geoClouds?.enabled)await this.prepare();};}
 stop(){this.generation++;this.abort?.abort();clearTimeout(this.timer);this.playing=false;this.loading=false;this.button.textContent='▶ 雲の流れを再生';this.button.setAttribute('aria-pressed','false');if(this.frames.length)this.label.textContent='一時停止 · '+(this.index+1)+' / '+this.frames.length+' 観測';}
 // Hours of the atmosphere between two observations being played; an hour until some are.
 stepHours(){const f=this.frames;if(!f||f.length<2)return 1;const a=parseStamp(f[0]),b=parseStamp(f[1]);return a&&b&&b>a?(b-a)/3600000:1;}
 // Milliseconds per observation, from the chosen hours per second.
 get interval(){return this.stepHours()/Math.max(this.hoursPerSecond,0.01)*1000;}
 async prepare(useBundle=false){this.stop();const generation=this.generation;const product=this.controller.ui.weatherProduct.value;if(product==='earth'){this.label.textContent='赤外線または可視光の観測を選んでください。';return;}const bundle=(await bundledSequence())?.[product]||[];let times=useBundle?bundle.map(f=>f.time):(this.controller.times[product]||[]).slice(-Math.max(2,this.frameCount||24));if(times.length<2){this.label.textContent='再生には2時刻以上の観測が必要です。「最新を取得」で更新してください。';return;}this.loading=true;this.abort=new AbortController();const signal=this.abort.signal;this.button.textContent='読み込みを中止';try{let next=0,done=0;const worker=async()=>{while(next<times.length){const time=times[next++];if(signal.aborted||generation!==this.generation)return;const key=product+':'+time;if(!this.controller.cache.has(key)){const saved=bundle.find(f=>f.time===time);const url=saved?.url||this.controller.imageAddress(product,time,512);const image=await this.controller.loadImage(url,signal);if(generation!==this.generation)return;this.controller.cache.set(key,{image,source:url,saved:!!saved});}done++;this.label.textContent=`観測を準備中 ${done} / ${times.length}`;}};await Promise.all(Array.from({length:Math.min(6,times.length)},worker));if(signal.aborted||generation!==this.generation)return;if(useBundle||!this.controller.times[product])this.controller.times[product]=times;this.frames=times;this.product=product;this.index=0;this.loading=false;this.playing=true;this.button.textContent='❚❚ 一時停止';this.button.setAttribute('aria-pressed','true');this.step();}catch(e){if(generation!==this.generation)return;this.abort?.abort();this.loading=false;this.playing=false;this.button.textContent='▶ 雲の流れを再生';this.label.textContent='観測の取得に失敗しました。表示中の観測を保持しています。';}}
 step(){if(!this.playing)return;if(document.hidden){this.timer=setTimeout(()=>this.step(),this.interval);return;}const c=this.controller,time=this.frames[this.index];const entry=c.cache.get(this.product+':'+time);if(!entry){this.stop();this.label.textContent='再生用の観測を再取得してください。';return;}this.continuing=this.index!==0;c.onImage(entry.image);this.continuing=false;c.onEnabled(true);c.current={product:this.product,time,saved:entry.saved};c.renderCurrent();c.done();this.label.textContent=`実観測を連続再生 · ${this.index+1} / ${this.frames.length} 時刻${this.index===0?' · 先頭から':''}`;const isLast=this.index===this.frames.length-1;this.index=(this.index+1)%this.frames.length;this.timer=setTimeout(()=>this.step(),isLast?this.interval*2:this.interval);}
}
root.WeatherPlayback=WeatherPlayback;
if(typeof module!=='undefined')module.exports={WeatherPlayback};
})(typeof window==='undefined'?globalThis:window);
